#include <bits/stdc++.h>
using namespace std;

class ERockPaperScissors {
public:
    int min;

    void check(vector<vector<int>> &aa, int a[], int b[]) {
        for (size_t i = 0; i < aa.size(); i++) {
            int m = min(a[aa[i][0]], b[aa[i][1]]);
            b[aa[i][1]] -= m;
            a[aa[i][0]] -= m;
        }
        int curr = 0;
        for (int i = 0; i < 3; i++) curr += a[i];
        min = std::min(min, curr);
    }

    void per(vector<vector<int>> &aa, int index, int a[], int b[]) {
        check(aa, a, b);
        for (size_t i = index; i < aa.size(); i++) {
            std::swap(aa[i], aa[index]);
            per(aa, index + 1, a, b);
            std::swap(aa[i], aa[index]);
        }
    }

    void solve() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        int n;
        cin >> n;
        int a[3], b[3];
        min = INT_MAX;
        int max_score = 0;
        for (int i = 0; i < 3; i++) {
            cin >> a[i];
        }
        for (int i = 0; i < 3; i++) {
            cin >> b[i];
        }
        max_score = min(a[0], b[1]) + min(a[1], b[2]) + min(a[2], b[0]);
        vector<vector<int>> aa = {
            {0, 0},
            {1, 1},
            {2, 2},
            {0, 2},
            {1, 0},
            {2, 1}
        };
        per(aa, 0, a, b);
        cout << min << " " << max_score << "\n";
    }
};

int main() {
    ERockPaperScissors solver;
    solver.solve();
    return 0;
